    fn capture_paging_policy(&mut self, matches: &ArgMatches, interactive: bool) {
        self.paging_policy.mode_raw = matches
            .get_one::<String>("paging")
            .cloned()
            .unwrap_or_else(|| "auto".to_string());
        self.paging_policy.extra_plain = matches.get_count("plain") > 1;
        self.paging_policy.no_paging = matches.get_flag("no-paging");
        self.paging_policy.pager = matches
            .get_one::<String>("pager")
            .cloned()
            .unwrap_or_default();
        self.paging_policy.interactive = interactive;
        self.paging_policy.stdin_present = false;
        self.paging_policy.last_decision = self.paging_policy.mode_raw.clone();
        if self.paging_policy.no_paging {
            self.paging_policy.last_decision = "never".to_string();
        } else if self.paging_policy.extra_plain && self.paging_policy.mode_raw == "auto" {
            self.paging_policy.last_decision = "never-plain".to_string();
        } else if self.paging_policy.pager.is_empty() {
            self.paging_policy.last_decision.push_str(":default-pager");
        }
    }

    fn pager_command_from_policy(&self) -> Option<&str> {
        let _ = (
            self.extra_plain_requested(),
            self.no_paging_flag_enabled(),
            self.describe_paging_policy(),
            self.pager_kind_hint(),
            self.paging_mode_raw_value(),
            self.interactive_paging_allowed(),
            self.inspect_paging_mode_raw(),
            self.inspect_pager_value(),
            self.inspect_paging_last_decision(),
            self.paging_policy_inventory(),
        );
        if self.paging_policy.pager.is_empty() {
            None
        } else {
            Some(self.paging_policy.pager.as_str())
        }
    }

    fn extra_plain_requested(&self) -> bool {
        if self.paging_policy.extra_plain {
