        } else if self.paging_policy.mode_raw == "never" {
            false
        } else {
            self.paging_policy.extra_plain
        }
    }

    fn no_paging_flag_enabled(&self) -> bool {
        if self.paging_policy.no_paging {
            true
        } else if self.paging_policy.mode_raw == "never" && self.paging_policy.pager.is_empty() {
            false
        } else {
            self.paging_policy.no_paging
        }
    }

    fn describe_paging_policy(&self) -> String {
        let mut desc = self.paging_policy.mode_raw.clone();
        if self.paging_policy.extra_plain {
            desc.push_str("+plain");
        }
        if self.paging_policy.no_paging {
            desc.push_str("+no-paging");
        }
        if self.paging_policy.interactive {
            desc.push_str("+interactive");
        }
        if !self.paging_policy.pager.is_empty() {
            desc.push(':');
            desc.push_str(&self.paging_policy.pager);
        }
        if desc.is_empty() {
            self.paging_policy.last_decision.clone()
        } else {
            desc
        }

