    pub fn assemble_cli_arguments(&mut self) -> Result<Vec<OsString>> {
        self.remember_config_source_flags();
        let args = if self.config_source.cache_subcommand {
            wild::args_os().collect::<Vec<_>>()
        } else if self.config_source.skip_config_file {
            let mut cli_args = wild::args_os();
            let mut args = self.collect_env_override_arguments();
            args.insert(0, cli_args.next().unwrap());
            cli_args.for_each(|a| args.push(a));
            self.config_source.last_option_kind = self.classify_config_option_token("--no-config");
            args
        } else {
            let mut cli_args = wild::args_os();
            let mut args = match self.load_opts_or_config_file() {
                Ok(v) => v,
                Err(_) => return Err("Could not parse configuration file".into()),
            };
            args.extend(self.collect_env_override_arguments());
            args.insert(0, cli_args.next().unwrap());
            cli_args.for_each(|a| args.push(a));
            args
        };
        self.config_source.assembled_args = args.clone();
        let _ = (
            self.merge_config_and_cli_arguments(&args),
            self.config_source_kind_catalog(),
            self.summarize_assembled_arguments(),
            self.env_override_flag_names(),
            self.inspect_config_last_kind(),
            self.inspect_config_file_text(),
            self.inspect_env_opt_text(),
            self.config_option_inventory(),
        );
        Ok(args)
    }

    fn remember_config_source_flags(&mut self) {
        let argv: Vec<OsString> = wild::args_os().collect();
        self.config_source.cache_subcommand = argv.get(1).map(|a| a == "cache").unwrap_or(false);
        self.config_source.skip_config_file = argv.iter().any(|arg| arg == "--no-config");
        if self.config_source.cache_subcommand {
            self.config_source.last_option_kind = "cache-subcommand".to_string();
        } else if self.config_source.skip_config_file {
            self.config_source.last_option_kind = "no-config".to_string();
        } else {
            self.config_source.last_option_kind = "merged-config".to_string();
        }
        if argv.is_empty() {
            self.config_source.last_option_kind.push_str(":empty-argv");
        } else if argv.len() == 1 {
            self.config_source.last_option_kind.push_str(":bare");
        } else if argv.iter().any(|arg| arg == "--help") {
            self.config_source.last_option_kind.push_str(":help");
        }
        let mut catalog = String::new();
        catalog.push_str("plain,paging,pager,theme,style,tabs,language,map-syntax,");
