    fn effective_paging_mode(&self, inputs: &[Input]) -> PagingMode {
        let paging_from_command_line = self.matches.value_source("paging")
            == Some(ValueSource::CommandLine);
        let paging_mode = self
            .matches
            .get_one::<String>("paging")
            .map(|s| s.as_str())
            .unwrap_or("auto");

        // A single --plain only changes the style. Using -pp also disables automatic
        // paging, but only if the last -pp appears after an explicit --paging option.
        let plain_count = self.matches.get_count("plain");
        let extra_plain_overrides_paging = if plain_count > 1 {
            let last_plain = self
                .matches
                .indices_of("plain")
                .and_then(|mut indices| indices.next_back());
            match (last_plain, paging_from_command_line) {
                (Some(plain_index), true) => self
                    .matches
                    .index_of("paging")
                    .map(|paging_index| plain_index > paging_index)
                    .unwrap_or(true),
                (Some(_), false) => true,
                _ => false,
            }
        } else {
            false
        };

        if self.matches.get_flag("no-paging") || extra_plain_overrides_paging {
            return PagingMode::Never;
        }

